SELECT id, service, host, latency_ms, status_code, payload_json, context, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, COALESCE(context['trace'], 'none') AS trace_or_default, context['trace'] AS trace FROM app_logs;
